#include <stdio.h>


int main(void)
{
    int a[] = {3, 2, 1};
    for (int j = 0; j < 2; j++) {
        if (a[j] > a[j + 1]) {
            int t = a[j];
            a[j] = a[j + 1];
            a[j + 1] = t;
        }
    }
    printf("%d %d %d\n", a[0], a[1], a[2]);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int swapped = 0;
    int a[] = {1, 2};
    if (a[0] > a[1]) {
        swapped = 1;
    }
    printf("%d\n", swapped);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int count = 0;
